<?php

declare(strict_types=1);

require_once __DIR__ . '/owner_layout.php';
require_once __DIR__ . '/owner_profile_copy.php';
require_once __DIR__ . '/final_profile_presentation.php';

/** @param array<string, mixed> $profile @param list<array<string, mixed>> $skills
 * @param list<string> $errors @param array<string, string> $fieldErrors */
function renderOwnerProfilePage(array $profile, ?int $profileId, string $profileVersion, int $profileCompletion, array $skills, string $message, array $errors, array $fieldErrors, ?int $submittedSkillId, string $submittedSkillValue): void
