        <div class="owner-profile-name" dir="auto"><h2><bdi dir="auto"><?php echo ownerEscapeHtml((string) ($profile['full_name'] ?: ownerText('Your name'))); ?></bdi></h2><p dir="auto"><bdi dir="auto"><?php echo ownerEscapeHtml((string) $profile['professional_title']); ?></bdi><?php echo !empty($profile['professional_title']) && !empty($profile['location']) ? ' · ' : ''; ?><bdi dir="auto"><?php echo ownerEscapeHtml((string) $profile['location']); ?></bdi></p></div>
        <div class="completion"><div class="completion-header"><span><?php echo ownerEscapeHtml(ownerText('Profile completion')); ?></span><strong><?php echo $profileCompletion; ?>%</strong></div><progress value="<?php echo $profileCompletion; ?>" max="100"><?php echo $profileCompletion; ?>%</progress></div>
<?php if ($profileId !== null): ?>
