    </section>
    <section id="about" class="owner-profile-panel" data-owner-profile-panel="about" aria-label="<?php echo $copy('about'); ?>"><div class="form-grid">
        <label class="form-field form-field-full" for="about_me"><span><?php echo ownerEscapeHtml(ownerText('About Me')); ?></span><textarea id="about_me" dir="auto" name="about_me" maxlength="<?php echo PERSONAL_INFO_FIELD_MAX_LENGTHS['about_me']; ?>"<?php echo ownerFieldAccessibilityAttributes($fieldErrors, 'about_me'); ?>><?php echo ownerEscapeHtml((string) $profile['about_me']); ?></textarea><?php ownerRenderFieldError($fieldErrors, 'about_me'); ?></label>
        <label class="form-field form-field-full" for="work_description"><span><?php echo ownerEscapeHtml(ownerText('Professional summary')); ?> <em><?php echo ownerEscapeHtml(ownerText('(optional)')); ?></em></span><textarea id="work_description" dir="auto" name="work_description" maxlength="<?php echo PERSONAL_INFO_FIELD_MAX_LENGTHS['work_description']; ?>"<?php echo ownerFieldAccessibilityAttributes($fieldErrors, 'work_description', 'professional-summary-help'); ?>><?php echo ownerEscapeHtml((string) $profile['work_description']); ?></textarea><small id="professional-summary-help" class="form-hint"><?php echo ownerEscapeHtml(ownerText('Add supporting context for your public Hero.')); ?></small><?php ownerRenderFieldError($fieldErrors, 'work_description'); ?></label>
        <h2 class="form-section-title"><?php echo ownerEscapeHtml(ownerText('Social Accounts')); ?></h2>
        <?php foreach (['linkedin_url' => 'LinkedIn URL', 'github_url' => 'GitHub URL', 'instagram_url' => 'Instagram URL', 'facebook_url' => 'Facebook URL', 'website_url' => 'Personal Website URL'] as $field => $label): ?>
            <label class="form-field" for="<?php echo $field; ?>"><span><?php echo ownerEscapeHtml(ownerText($label)); ?></span><input type="url" dir="ltr" id="<?php echo $field; ?>" name="<?php echo $field; ?>" value="<?php echo ownerEscapeHtml((string) $profile[$field]); ?>" maxlength="<?php echo PERSONAL_INFO_FIELD_MAX_LENGTHS[$field]; ?>"<?php echo ownerFieldAccessibilityAttributes($fieldErrors, $field); ?>><?php ownerRenderFieldError($fieldErrors, $field); ?></label>
        <?php endforeach; ?>
    </div></section>
    <footer class="owner-profile-save" data-owner-profile-save>
        <span class="owner-profile-save-status"><?php if ($message !== ''): ?><?php echo evidenceHubOwnerIcon('check'); ?><?php echo ownerEscapeHtml($message); ?><?php else: ?><?php echo $copy('save_hint'); ?><?php endif; ?></span>
        <a class="button-link" href="owner_profile.php"><?php echo ownerEscapeHtml(ownerText('Cancel')); ?></a>
        <button class="button-primary" type="submit" data-pending-label="<?php echo ownerEscapeHtml(ownerText('Saving changes…')); ?>"><?php echo evidenceHubOwnerIcon('check'); ?><?php echo ownerEscapeHtml(ownerText('Save Changes')); ?></button>
    </footer>
    </form>
    <section id="skills" class="owner-profile-panel owner-profile-skills" data-owner-profile-panel="skills" aria-label="<?php echo $copy('skills'); ?>">
<div class="section-heading-row"><h2><?php echo ownerEscapeHtml(ownerText('Skills')); ?></h2><span class="muted"><?php echo count($skills); ?> <?php echo ownerEscapeHtml(ownerText('added')); ?></span></div>
<?php if ($skills === []): ?><div class="empty-state admin-empty"><strong><?php echo ownerEscapeHtml(ownerText('No skills added yet')); ?></strong><span><?php echo ownerEscapeHtml(ownerText('Add your first skill to help visitors understand your strengths.')); ?></span></div><?php endif; ?>
<div class="skills-chips"><?php foreach ($skills as $skill): $skillFieldErrors = $submittedSkillId === (int) $skill['id'] ? $fieldErrors : []; ?><div class="skill-row"><form method="POST" action="owner_profile.php" data-owner-form><input type="hidden" name="action" value="update_skill"><input type="hidden" name="csrf_token" value="<?php echo ownerEscapeHtml(getCsrfToken()); ?>"><input type="hidden" name="skill_id" value="<?php echo (int) $skill['id']; ?>"><label class="visually-hidden" for="skill_<?php echo (int) $skill['id']; ?>"><?php echo ownerEscapeHtml(ownerText('Skill name')); ?></label><input id="skill_<?php echo (int) $skill['id']; ?>" type="text" dir="auto" name="skill_name" value="<?php echo ownerEscapeHtml((string) $skill['skill_name']); ?>" maxlength="<?php echo SKILL_NAME_MAX_LENGTH; ?>" required<?php echo ownerFieldAccessibilityAttributes($skillFieldErrors, 'skill_name'); ?>><button type="submit" class="button-secondary" data-pending-label="<?php echo ownerEscapeHtml(ownerText('Saving skill…')); ?>"><?php echo ownerEscapeHtml(ownerText('Save')); ?></button><?php ownerRenderFieldError($skillFieldErrors, 'skill_name'); ?></form><form method="POST" action="owner_profile.php" data-owner-form data-confirm="<?php echo ownerEscapeHtml(sprintf(ownerProfileCopy('remove_skill_confirm', $locale), (string) $skill['skill_name'])); ?>" data-confirm-title="<?php echo ownerEscapeHtml(ownerText('Remove skill?')); ?>" data-confirm-action="<?php echo ownerEscapeHtml(ownerText('Remove skill')); ?>"><input type="hidden" name="action" value="delete_skill"><input type="hidden" name="csrf_token" value="<?php echo ownerEscapeHtml(getCsrfToken()); ?>"><input type="hidden" name="skill_id" value="<?php echo (int) $skill['id']; ?>"><button type="submit" class="button-danger" data-pending-label="<?php echo ownerEscapeHtml(ownerText('Removing skill…')); ?>"><?php echo ownerEscapeHtml(ownerText('Remove')); ?></button></form></div><?php endforeach; ?></div>
<?php $skillAddFieldErrors = $submittedSkillId === null ? $fieldErrors : []; ?><form class="skill-add-form" method="POST" action="owner_profile.php" data-owner-form><input type="hidden" name="action" value="add_skill"><input type="hidden" name="csrf_token" value="<?php echo ownerEscapeHtml(getCsrfToken()); ?>"><label class="form-field" for="skill_name"><span><?php echo ownerEscapeHtml(ownerText('Skill Name')); ?> <?php ownerRenderRequiredIndicator(); ?></span><input type="text" id="skill_name" dir="auto" name="skill_name" value="<?php echo ownerEscapeHtml($submittedSkillId === null ? $submittedSkillValue : ''); ?>" maxlength="<?php echo SKILL_NAME_MAX_LENGTH; ?>" required<?php echo ownerFieldAccessibilityAttributes($skillAddFieldErrors, 'skill_name'); ?>></label><?php ownerRenderFieldError($skillAddFieldErrors, 'skill_name'); ?><button class="button-primary" type="submit" data-pending-label="<?php echo ownerEscapeHtml(ownerText('Adding skill…')); ?>"><?php echo ownerEscapeHtml(ownerText('Add Skill')); ?></button></form>
    </section>
</div>
    <?php
}
